"""v2 — CH-57: scope (P1). DEC-321..325, Q-50. PRD-01, PRD-02, 04-00, PRD-12, Master Index."""
from v2lib import *
SRC = 'پیشنهاد ChatGPT P1'

def p01(s):
    s = front(s, '1.2', 'v2 — CH-57: BO-06، PS-06، LG-03؛ §1.7 جایگزین و Purchase Rescue به نسخه جاری آمدند (DEC-321)')
    s = after_line(s, '| ‏BO-05 | ‏جلوگیری از رهاشدن درخواست حل‌نشده |',
        row('BO-06 *(v2)*', 'کمک به یافتن محصول مناسب و ادامه خرید', 'مشتری محصول مناسب یا جایگزین موجود را با دلیل می‌بیند و مانع خریدش با اطلاعات درست برطرف می‌شود؛ **در Prototype فقط آمادگی سنجش** (DEC-16 و ND-40 برقرار)', 'BR-08 *(v2؛ در BRD نیست)*', 'PER-01، PER-03'))
    s = after_line(s, '| ‏LG-01 **(تأییدشده — DEC-12)**',
        row('LG-03 *(v2 — DEC-321)*', 'آزمودن اینکه کمک به خرید (پیشنهاد با دلیل، جایگزین، رفع مانع) با همان مرزهای صحت ممکن است و داده تقاضا (جست‌وجوی بی‌نتیجه، ناموجود، نیاز پوشش‌نداده) برای فروشگاه قابل استفاده است', 'نمایش، شمار رویدادهای KM-21 تا KM-27، فهرست محدودیت‌ها', SRC))
    s = after_line(s, '| ‏PS-05 | ‏**قابل‌بررسی بودن**',
        row('PS-06 *(v2)*', '**کمک به انتخاب و ادامه خرید:** پیشنهاد محصول با دلیل، جایگزین برای ناموجود، رفع تردید پیش از رهاشدن خرید، و ثبت تقاضای پوشش‌داده‌نشده', 'PER-01، PER-03', 'BO-06', SRC))
    s = R(s, '| ‏شخصی‌سازی و کشف پیشرفته: جست‌وجوی تصویری، پیشنهاد ست، جایگزین شخصی‌سازی‌شده، پرو مجازی | ‏آینده (مرحله ۲) — PRD-12 |',
             '| ‏شخصی‌سازی و کشف پیشرفته: جست‌وجوی تصویری، پیشنهاد ست، ~~جایگزین شخصی‌سازی‌شده~~، پرو مجازی | ‏آینده (مرحله ۲) — PRD-12. **v2 (DEC-321):** پیشنهاد جایگزین بر پایه ترجیحات گفته‌شده در همین گفت‌وگو به نسخه جاری آمد (EP-08)؛ شخصی‌سازی بر پایه رفتار همچنان بیرون است (ND-34؛ DEC-323) |')
    s = R(s, '| ‏نجات خرید در آستانه رهاشدن (Purchase Rescue) | ‏آینده — PRD-12',
             '| ‏~~نجات خرید در آستانه رهاشدن (Purchase Rescue)~~ | ‏**جایگزین‌شده با DEC-321 (v2) — CH-57:** شکل واکنشی آن در نسخه جاری است (US-08-03). *متن قبلی:* آینده — PRD-12')
    s = R(s, '| ‏انجام خرید: ثبت سفارش، پرداخت، تغییر سفارش، بازپرداخت خودکار | ‏خارج از مرز اختیارات؛ ریسک مالی |',
             '| ‏انجام خرید: ثبت سفارش، پرداخت، تغییر سفارش، بازپرداخت خودکار | ‏خارج از مرز اختیارات؛ ریسک مالی. **v2 (DEC-322):** هر عملیات اجرایی فقط با ضرورت برای MVP، ابزار معتبر و تأیید صریح مشتری؛ در Prototype ابزاری نیست، پس هیچ |')
    return hist(s, '1.2', 'v2 — CH-57: BO-06، LG-03، PS-06؛ §1.7 ردیف‌های جایگزین، Purchase Rescue و انجام خرید (DEC-321، DEC-322، DEC-323)', 'CH-57')

def p02(s):
    s = front(s, '1.3', 'v2 — CH-57: جزء ۷ کمک به خرید؛ §2.8 مرحله ۲ به نسخه جاری آمد (DEC-321)')
    s = after_line(s, '| ‏**جزء ۶ — سنجش و ممیزی** |',
        row('**جزء ۷ — کمک به خرید** *(v2)*', 'نیاز و ترجیحات گفته‌شده را می‌فهمد، محصول مناسب را با دلیل پیشنهاد می‌دهد، برای گونه ناموجود جایگزین موجود و نزدیک می‌آورد، مانع خرید را می‌شناسد و با اطلاعات یا گزینه مناسب پاسخ می‌دهد، و تقاضای پوشش‌داده‌نشده را ثبت می‌کند. اقدام اجرایی ندارد (DEC-322)', 'PER-01، PER-03', 'BR-08 *(v2)*', 'PS-06', 'EP-08 *(v2)*', 'الزامی؛ بیرون از هسته محافظت‌شده (DEC-325)'))
    s = R(s, '  E["جزء ۶: سنجش و ممیزی"]', '  E["جزء ۶: سنجش و ممیزی"]\n  SH["جزء ۷: کمک به خرید (v2)"]')
    s = R(s, '  A & H & P & M --> E', '  A -- "یافتن محصول، جایگزین، مانع خرید" --> SH\n  D -- "فقط داده تأییدشده" --> SH\n  SH & A & H & P & M --> E')
    s = R(s, '| ‏مرحله ۲ — Shopping Assistant | ‏پیشنهاد جایگزین، رفع موانع خرید (از جمله Purchase Rescue) و شخصی‌سازی |',
             '| ‏مرحله ۲ — Shopping Assistant | ‏~~پیشنهاد جایگزین، رفع موانع خرید (از جمله Purchase Rescue)~~ **← در نسخه جاری (جزء ۷؛ DEC-321، v2)**؛ می‌ماند: شخصی‌سازی بر پایه رفتار، جست‌وجوی تصویری، ست و مکمل |')
    s = R(s, '| ‏مرحله ۳ — Agentic Commerce | ‏اجرای فرایندهای چندمرحله‌ای با اجازه مشتری |',
             '| ‏مرحله ۳ — Agentic Commerce | ‏اجرای فرایندهای چندمرحله‌ای با اجازه مشتری. **v2:** زیرسازی داده و ابزارها از نسخه جاری (DEC-324) |')
    return hist(s, '1.3', 'v2 — CH-57: جزء ۷ کمک به خرید در §2.3 و دیاگرام؛ §2.8 (DEC-321، DEC-324)', 'CH-57')

def p0400(s):
    s = front(s, '1.3', 'v2 — CH-57: ND-33 و ND-35 (DEC-321)؛ یادداشت عملیات اجرایی (DEC-322)')
    s = R(s, '| ‏ND-33 | ‏جست‌وجوی تصویری، پیشنهاد ست، جایگزین شخصی‌سازی‌شده، پرو مجازی | ‏آینده (مرحله ۲) |',
             '| ‏ND-33 | ‏جست‌وجوی تصویری، پیشنهاد ست، ~~جایگزین شخصی‌سازی‌شده~~، پرو مجازی. *(v2 — DEC-321: پیشنهاد جایگزین بر پایه ترجیحات همین گفت‌وگو در EP-08 مجاز شد؛ جایگزین بر پایه رفتار زیر ND-34 می‌ماند)* | ‏آینده (مرحله ۲)؛ زیرسازی داده از نسخه جاری (DEC-324) |')
    s = R(s, '| ‏ND-34 | ‏موتور شخصی‌سازی بر اساس رفتار مشتری (پیشنهاد ساده از کاتالوگ با آن فرق دارد) | ‏آینده |',
             '| ‏ND-34 | ‏موتور شخصی‌سازی بر اساس رفتار مشتری (پیشنهاد ساده از کاتالوگ با آن فرق دارد). *(v2 — DEC-323: ترجیحات فقط از همین گفت‌وگو؛ این قاعده موجود PRD است، نه از P1)* | ‏آینده |')
    s = R(s, '| ‏ND-35 | ‏Purchase Rescue و Agentic Commerce | ‏آینده (مرحله ۲ و ۳) |',
             '| ‏ND-35 | ‏~~Purchase Rescue و~~ Agentic Commerce. *(v2 — DEC-321: Purchase Rescue واکنشی در EP-08 مجاز شد؛ DEC-322: عملیات اجرایی فقط با ضرورت، ابزار معتبر و تأیید صریح مشتری)* | ‏آینده (مرحله ۳) |')
    return hist(s, '1.3', 'v2 — CH-57: ND-33، ND-34، ND-35 با یادداشت v2 (DEC-321 تا DEC-323)', 'CH-57')

def p12(s):
    s = front(s, '1.3', 'v2 — CH-57: FS-09 و FS-12 به انتشار ۱ آمدند (DEC-321)؛ زیرسازی انتشار ۳ و ۴ (DEC-324)')
    s = R(s, '| ‏انتشار ۱ — Prototype *(تعهدشده؛ PRD-11)* | ‏UC-01 تا UC-08 (PRD-11 §11.3) |',
             '| ‏انتشار ۱ — Prototype *(تعهدشده؛ PRD-11)* | ‏UC-01 تا UC-08 (PRD-11 §11.3) · **v2:** FS-09 و FS-12 (EP-08؛ DEC-321) |')
    s = R(s, '| ‏انتشار ۳ — AI Shopping Assistant *(جهت، تعهدنشده)* | ‏FS-09 پیشنهاد جایگزین برای گونه ناموجود',
             '| ‏انتشار ۳ — AI Shopping Assistant *(جهت، تعهدنشده)* | ‏~~FS-09 پیشنهاد جایگزین برای گونه ناموجود~~ *(v2 ← انتشار ۱)*')
    s = R(s, 'FS-12 رفع تردید پیش از ره', '~~FS-12 رفع تردید پیش از ره')
    s = re.sub(r'(~~FS-12 رفع تردید پیش از ره[^·|]*?)( ·| \|)', lambda m: m.group(1).rstrip() + '~~ *(v2 ← انتشار ۱)*' + m.group(2), s, count=1)
    s = R(s, '| ‏FS-09 | ‏گونه‌ای که مشتری می‌خواهد', '| ‏FS-09 *(v2 — به انتشار ۱ آمد: US-08-02؛ DEC-321)* | ‏گونه‌ای که مشتری می‌خواهد')
    s = R(s, '| ‏FS-12 | ‏مشتری درباره سایز', '| ‏FS-12 *(v2 — به انتشار ۱ آمد: US-08-03؛ DEC-321)* | ‏مشتری درباره سایز')
    s = before_line(s, '## ‏۱۲.۷ انتشار ۴ — Agentic Commerce',
        '> ‏**v2 — زیرسازی از انتشار ۱ (DEC-324):** برای FS-10 و FS-11 مدل داده چند تصویر، ویژگی ساختاریافته و رابطه «مشابه، جایگزین، مکمل» (DS-10 تا DS-12) و لایه جست‌وجوی مستقل با ورودی قابل گسترش (متن، ویژگی؛ تصویر فقط در رابط) از Prototype ساخته می‌شوند. برای Product Insights Agent، داده ساختاریافته موضوع، مانع و تقاضا از امروز ثبت می‌شود (US-08-04). ساخت خود این قابلیت‌ها همچنان «جهت، تعهدنشده» است.\n')
    s = before_line(s, '## ‏۱۲.۸ بدون برنامه',
        '> ‏**v2 — زیرسازی انتشار ۴ (DEC-324):** هر قابلیت دستیار در معماری یک «ابزار» با سطح دسترسی صریح است؛ در انتشار ۱ همه ابزارها فقط خواندنی‌اند و تنها کنش نوشتنی ثبت ارجاع است. عملیات اجرایی فقط با ضرورت، ابزار معتبر و تأیید صریح مشتری (DEC-322).\n')
    return hist(s, '1.3', 'v2 — CH-57: §12.3 و §12.6 FS-09 و FS-12 به انتشار ۱؛ یادداشت زیرسازی انتشار ۳ و ۴ (DEC-321، DEC-322، DEC-324)', 'CH-57')

DECS = [
 row('DEC-321', '**v2 — دامنه MVP (P1):** مرحله اول (هوشمندسازی پشتیبانی) و مرحله دوم (هوشمندسازی خرید) هر دو در Prototype. مرحله دوم = اپیک تازه **EP-08 کمک به خرید** (جزء ۷، BR-08، PS-06، BO-06، LG-03): پیشنهاد محصول با دلیل، جایگزین، Purchase Rescue واکنشی، ثبت درخواست‌ها؛ به‌علاوه ویژگی ساختاریافته، تصویر، قابلیت‌های دستیار و لحن. *(جایگزین بخش «جایگزین» ND-33، بخش Purchase Rescue ND-35، PRD-01 §1.7 ردیف‌های ۲ و ۳، و جای FS-09 و FS-12 در PRD-12)*', D, 'PRD-01، PRD-02، PRD-04-00، PRD-12؛ ' + SRC, 'CH-57'),
 row('DEC-322', '**v2 — عملیات اجرایی (قاعده مشروط P1):** دستیار بدون تأیید صریح مشتری هیچ عملیات خرید یا پرداختی انجام نمی‌دهد؛ هر عملیات اجرایی فقط وقتی افزوده می‌شود که برای جریان MVP ضروری باشد، ابزار معتبرش موجود باشد و تأیید مناسب مشتری گرفته شود. در Prototype ابزار اجرایی نیست (ND-31)، پس عملیات اجرایی هم نیست', D, 'PRD-01 §1.7؛ ND-35؛ ' + SRC, 'CH-57'),
 row('DEC-323', '**v2 — ترجیحات مشتری:** فقط آنچه مشتری در همین گفت‌وگو گفته است؛ شخصی‌سازی بر پایه رفتار یا سابقه بیرون می‌ماند (ND-34). *قاعده موجود PRD، نه از P1*', D, 'ND-34؛ EP-08', 'CH-57'),
 row('DEC-324', '**v2 — زیرسازی مرحله سوم:** ویژگی ساختاریافته، چند تصویر برای هر محصول، رابطه «مشابه، جایگزین، مکمل» فقط در داده، لایه جست‌وجو و پیشنهاد مستقل با ورودی متن و ویژگی (تصویر فقط در رابط)، ثبت ساختاریافته رویدادها، ابزارهای دستیار با سطح دسترسی (همه فقط خواندنی جز ثبت ارجاع). ساخت جست‌وجوی تصویری، ست و مکمل، Insights Agent و Agentic Commerce در PRD-12 می‌ماند', D, 'PRD-12 §12.6، §12.7؛ DD؛ 05 - Architecture؛ ' + SRC, 'CH-57'),
 row('DEC-325', '**v2 — برنامه:** هر دو مرحله در همان ۱۰ روز کاری (انتخاب Ava؛ تمدید احتمالی ۵ روز هنوز تصمیم نیست — Q-50). EP-08 بیرون از هسته محافظت‌شده؛ ترتیب کاهش: ۱ Purchase Rescue · ۲ جایگزین · ۳ مدیریت تصویر در پنل · ۴ خط دلیل پیشنهاد؛ ثبت رویدادهای تقاضا حذف نمی‌شود. ریسک RSK-27', D, 'PRD-11، PRD-11a، PRD-08؛ EP-08', 'CH-57'),
]

def mi(s):
    s = re.sub(r'^version: .*$', 'version: 1.14', s, count=1, flags=re.M)
    s = mi_dec(s, DECS)
    s = after_line(s, '| ‏Q-49 |', row('Q-50', '**v2:** آیا برنامه Prototype با EP-08 پنج روز کاری تمدید می‌شود (۱۵ روز)؟ تا تصمیم، همه در ۱۰ روز با ترتیب کاهش DEC-325 (CH-57)', 'تمدید ۵ روز، یا ۱۰ روز با ترتیب کاهش', 'PRD-11، PRD-11a'))
    s = R(s, '| ‏**خارج از محدوده (مرحله نخست)** | ‏اتصال اینستاگرام (در Prototype)، جست‌وجوی تصویری، پیشنهاد ست، جایگزین شخصی‌سازی‌شده,',
             '| ‏**خارج از محدوده (مرحله نخست)** | ‏اتصال اینستاگرام (در Prototype)، جست‌وجوی تصویری، پیشنهاد ست، جایگزین شخصی‌سازی‌شده,') if 'جایگزین شخصی‌سازی‌شده,' in s else s
    s = before_line(s, '| ‏**خارج از محدوده (مرحله نخست)** |',
        row('**v2 — کمک به خرید (DEC-321، CH-57)**', 'اپیک EP-08 و جزء ۷: پیشنهاد محصول با دلیل، جایگزین برای ناموجود، Purchase Rescue واکنشی، ثبت درخواست‌ها و نیازها؛ ویژگی ساختاریافته و تصویر محصول؛ قابلیت‌های دستیار و لحن. **از «خارج از محدوده» پایین:** «جایگزین شخصی‌سازی‌شده» فقط بخش رفتارمحور بیرون می‌ماند و «Purchase Rescue» به نسخه جاری آمد. عملیات اجرایی: DEC-322. زیرسازی مرحله سوم: DEC-324'))
    s = mi_doc(s, 'PRD-01 - Goals', '1.2 (CH-44، CH-57 v2)', 'v2')
    s = mi_doc(s, 'PRD-02 - Solution', '1.3 (CH-32، CH-42، CH-57 v2)', 'v2')
    s = mi_doc(s, "PRD-04-00 - Product-wide Rules & Don'ts", '1.3 (CH-41، CH-42، CH-54، CH-57 v2)', 'v2')
    s = mi_doc(s, 'PRD-12 - Future Release Plan (فهرست)', '1.3 (CH-41، CH-45، CH-54، CH-57 v2)', 'v2')
    s = mi_ch(s, row('CH-57', D, '**v2 — پیشنهاد ChatGPT، مورد P1 (دامنه):** DEC-321 تا DEC-325 و Q-50. مرحله دوم «هوشمندسازی خرید» به Prototype آمد (EP-08، جزء ۷، BR-08، PS-06، BO-06، LG-03)؛ قاعده مشروط عملیات اجرایی؛ ترجیحات فقط از همین گفت‌وگو؛ زیرسازی مرحله سوم؛ همه در ۱۰ روز با ترتیب کاهش. نسخه‌ها: PRD-01 1.2، PRD-02 1.3، 04-00 1.3، PRD-12 1.3، Master Index 1.14', 'PRD-01، PRD-02، 04-00، PRD-12، Master Index'))
    return s

rw(S + 'PRD-01 - Goals.md', p01)
rw(S + 'PRD-02 - Solution.md', p02)
